// The site switches that the admin can change from the dashboard (/admin/visitor-analytics) without a new deploy.
// You do not edit this file.
//
// How it works: the values written in eventSwitches.js and upcomingConfig.js stay the DEFAULTS. Once per visit the
// site asks /api/settings what the admin changed. If the admin changed something, that wins. If not, the file wins.
// The last answer is kept in the browser, so a returning visitor sees the right thing from the first frame.
import { useSyncExternalStore } from 'react';

const CACHE_KEY = 'scc-live-settings-v1';

function readCache() {
  try {
    const v = JSON.parse(window.localStorage.getItem(CACHE_KEY) || '{}');
    return v && typeof v === 'object' ? v : {};
  } catch { return {}; }
}

let state = typeof window === 'undefined' ? {} : readCache();
const listeners = new Set();
let started = false;

const subscribe = (fn) => { listeners.add(fn); return () => listeners.delete(fn); };
const getSnapshot = () => state;

export function startLiveSettings() {
  if (started || typeof window === 'undefined') return;
  started = true;
  fetch('/api/settings', { headers: { Accept: 'application/json' }, cache: 'no-store' })
    .then((r) => (r.ok ? r.json() : null))
    .then((d) => {
      if (!d || !d.settings || typeof d.settings !== 'object') return;
      state = d.settings;
      try { window.localStorage.setItem(CACHE_KEY, JSON.stringify(state)); } catch { /* storage blocked: fine */ }
      listeners.forEach((fn) => fn());
    })
    .catch(() => { /* offline or no storage on the server: the file values stay in charge */ });
}

// the admin's value for `key`, or `fallback` (the value from the code file) when the admin did not change it
export function liveValue(key, fallback) {
  const v = state[key];
  return v === undefined || v === null ? fallback : v;
}

// re-renders the component when the answer from /api/settings arrives
export function useLiveSettings() {
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

export function useSwitch(key, fallback) {
  useLiveSettings();
  return liveValue(key, fallback);
}

startLiveSettings();
